using System;using System.IO;using System.Linq;using System.Threading.Tasks;using System.Windows;using System.Windows.Controls;using System.Windows.Input;using System.Windows.Media;
namespace MacFlow {
 internal sealed class ShelfStore {
  private readonly string root;private readonly object gate=new object();internal ShelfStore(string profile){root=Path.Combine(profile,"shelf");Directory.CreateDirectory(root);}internal string[] Files{get{return Directory.GetFiles(root).OrderByDescending(File.GetCreationTimeUtc).Take(32).ToArray();}}
  internal Task<string> Add(string source){return Task.Run(()=>{lock(gate){var info=new FileInfo(source);if(!info.Exists||(info.Attributes&FileAttributes.ReparsePoint)!=0||info.Length>32*1024*1024)throw new IOException("Elegí un archivo de hasta 32 MB.");if(Files.Length>=32||Files.Sum(f=>new FileInfo(f).Length)+info.Length>128*1024*1024)throw new IOException("Shelf lleno. Retirá archivos.");string path=Path.Combine(root,Guid.NewGuid().ToString("N")+"_"+info.Name);File.Copy(source,path,false);return path;}});}
  internal void Remove(string file){string path=Path.GetFullPath(file);if(!String.Equals(Path.GetDirectoryName(path),Path.GetFullPath(root),StringComparison.OrdinalIgnoreCase))throw new IOException("Archivo fuera del Shelf");File.Delete(path);}internal static string Name(string path){string name=Path.GetFileName(path);return name.Length>33?name.Substring(33):name;}
 }
 internal sealed class IslandShelf : Window {
  private readonly ShelfStore store;private readonly StackPanel rows=new StackPanel();private readonly TextBlock status;private bool closed,busy;private static IslandShelf current;
  internal static Window View{get{return current;}}
  internal static void Open(Desktop desktop,string[] files){if(!WindowLife.Alive(current)){current=new IslandShelf(desktop);current.Show();DisplaySpace.Center(current,.12);Design.Reveal(current);}else if(!desktop.IsTesting)current.Activate();if(files!=null)current.AddFiles(files);}
  private IslandShelf(Desktop desktop){store=new ShelfStore(desktop.Store.DirectoryPath);Title="MacOS · Shelf";Width=470;Height=390;WindowStyle=WindowStyle.None;ResizeMode=ResizeMode.NoResize;ShowInTaskbar=false;Topmost=true;Background=Design.Brush("#141416");WindowLife.Track(this);Owner=desktop.TopBar;AllowDrop=true;
   var body=new DockPanel();var header=new DockPanel();var close=Design.Button("Cerrar",()=>Design.Dismiss(this),false);DockPanel.SetDock(close,Dock.Right);header.Children.Add(close);header.Children.Add(Design.Text("Shelf",23,true));DockPanel.SetDock(header,Dock.Top);body.Children.Add(header);status=Design.Text("Arrastrá archivos aquí o sobre la isla. Guardamos una copia local.",12,false);status.TextWrapping=TextWrapping.Wrap;status.Margin=new Thickness(0,10,0,12);DockPanel.SetDock(status,Dock.Top);body.Children.Add(status);body.Children.Add(new ScrollViewer{Content=rows,VerticalScrollBarVisibility=ScrollBarVisibility.Auto});Content=Design.Glass(body,28,false);SourceInitialized+=delegate{Native.Glass(this,Design.Dark);};Drop+=delegate(object sender,DragEventArgs e){if(e.Data.GetDataPresent(DataFormats.FileDrop)){AddFiles((string[])e.Data.GetData(DataFormats.FileDrop));e.Handled=true;}};DragOver+=delegate(object sender,DragEventArgs e){e.Effects=e.Data.GetDataPresent(DataFormats.FileDrop)?DragDropEffects.Copy:DragDropEffects.None;e.Handled=true;};KeyDown+=delegate(object sender,KeyEventArgs e){if(e.Key==Key.Escape)Design.Dismiss(this);};Closed+=delegate{closed=true;if(current==this)current=null;};Refresh();}
  private async void AddFiles(string[] files){if(busy||closed)return;busy=true;try{foreach(var file in files.Take(32)){await store.Add(file);if(closed)return;}status.Text="Copias locales · arrastrá para recuperar · hasta 128 MB.";Refresh();}catch(Exception ex){if(!closed)status.Text=ex.Message;}finally{busy=false;}}
  private void Refresh(){rows.Children.Clear();foreach(var file in store.Files){string path=file;var row=new DockPanel{Margin=new Thickness(0,4,0,4)};var remove=Design.Button("Retirar",delegate{try{store.Remove(path);Refresh();}catch(Exception ex){status.Text=ex.Message;}},false);DockPanel.SetDock(remove,Dock.Right);row.Children.Add(remove);var preview=Design.Button(ShelfStore.Name(path),()=>Preview(path),false);preview.HorizontalContentAlignment=HorizontalAlignment.Left;Point start=new Point();preview.PreviewMouseLeftButtonDown+=delegate(object sender,MouseButtonEventArgs e){start=e.GetPosition(preview);};preview.MouseMove+=delegate(object sender,MouseEventArgs e){if(e.LeftButton==MouseButtonState.Pressed&&(e.GetPosition(preview)-start).Length>8)DragDrop.DoDragDrop(preview,new DataObject(DataFormats.FileDrop,new[]{path}),DragDropEffects.Copy);};row.Children.Add(preview);rows.Children.Add(row);}}
  private void Preview(string path){try{var panel=Design.Panel("MacOS · Vista previa",570,420);UIElement content;string ext=Path.GetExtension(path).ToLowerInvariant();if(new[]{".txt",".md",".csv",".json",".log"}.Contains(ext)&&new FileInfo(path).Length<524288)content=new TextBox{Text=File.ReadAllText(path),IsReadOnly=true,TextWrapping=TextWrapping.Wrap,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};else if(new[]{".png",".jpg",".jpeg",".bmp"}.Contains(ext)){var bitmap=new System.Windows.Media.Imaging.BitmapImage();bitmap.BeginInit();bitmap.CacheOption=System.Windows.Media.Imaging.BitmapCacheOption.OnLoad;bitmap.DecodePixelWidth=900;bitmap.UriSource=new Uri(path);bitmap.EndInit();bitmap.Freeze();content=new Image{Source=bitmap,Stretch=Stretch.Uniform};}else content=Design.Text(ShelfStore.Name(path)+" — arrastrá para recuperar. Vista previa no disponible para este formato.",15,false);panel.Content=Design.Glass(content,24,false);panel.Show();DisplaySpace.Center(panel,.16);Design.Reveal(panel);}catch(Exception ex){status.Text=ex.Message;}}
 }
}
